import { FC, HTMLAttributes, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { useDispatch } from 'react-redux';
import { useNavigate } from 'react-router-dom';

import { Button, Form, Input, Select, Typography } from 'antd';
import cn from 'classnames';
import { useFormik } from 'formik';
import * as Yup from 'yup';

import { AppDispatch } from 'app/appStore';
import { Source, useSourcesCreateMutation, useSourcesUpdateMutation } from 'entities/Source';
import {
	EOnboardingStates,
	EOnboardingSteps,
	setModalState,
	setSourceForm,
	setStep,
	setThirdStateComplete,
} from 'features/Onboarding';
import { useMetaRetrieveQuery } from 'shared/api';
import { VALIDATION_MESSAGES } from 'shared/consts';
import { EGaCategories, EGaEvents, EGaTypes, EMainRoutes } from 'shared/typings';
import { OverlayLoader } from 'shared/ui';
import { formatQuery, getApiErrors, sendGaEvent } from 'shared/utils';

import styles from './SourceForm.module.scss';

interface ISourceFormProps extends HTMLAttributes<HTMLDivElement> {
	initialState: Source;
	isEditing?: boolean;
	isFetching?: boolean;
	sourceUuid?: string;
	step?: EOnboardingSteps;
}

export const SourceForm: FC<ISourceFormProps> = ({
	className,
	initialState,
	isEditing,
	isFetching,
	sourceUuid,
	step,
	...props
}) => {
	const { t } = useTranslation();
	const navigate = useNavigate();
	const dispatch = useDispatch<AppDispatch>();
	const [addSource, { isLoading: isAddLoading, error: addError, isSuccess: isAddSuccess }] = useSourcesCreateMutation();
	const [updateSource, { isLoading: isUpdateLoading, error: updateError, isSuccess: isUpdateSuccess }] =
		useSourcesUpdateMutation();
	const { data: metaData, isLoading: isMetaLoading } = useMetaRetrieveQuery();

	const { values, errors, handleSubmit, setFieldValue, setValues, isValid, dirty, setErrors } = useFormik({
		initialValues: initialState,
		validationSchema: Yup.object({
			name: Yup.string().required(VALIDATION_MESSAGES.required),
			url: Yup.string().url(VALIDATION_MESSAGES.url),
		}),
		onSubmit: (values) => {
			if (!step) {
				isEditing && sourceUuid ? updateSource({ uuid: sourceUuid, source: values }) : addSource(values);
			} else {
				if (step === EOnboardingSteps.THIRD) {
					sendGaEvent(EGaEvents.CLICK_NEXT, step3EventOptions);
					addSource(values);
				} else {
					sendGaEvent(EGaEvents.CLICK_NEXT, step2EventOptions);
					dispatch(setStep(EOnboardingSteps.THIRD));
				}
			}
		},
	});

	const step2EventOptions = {
		event_option1: EGaCategories.ONBOARDING,
		event_option2: EGaTypes.POPUP_STEP_TWO,
	};

	const step3EventOptions = {
		event_option1: EGaCategories.ONBOARDING,
		event_option2: EGaTypes.POPUP_STEP_THREE,
		event_option4: values.countries?.length
			? formatQuery(values.countries, metaData?.countryOptions || [])
			: 'undefined',
	};

	const handleGoToCatalog = () => {
		sendGaEvent(EGaEvents.CLICK_CATALOG, step === EOnboardingSteps.SECOND ? step2EventOptions : step3EventOptions);
		dispatch(setSourceForm(values));
		dispatch(setModalState(EOnboardingStates.FINAL));
	};

	useEffect(() => {
		if (addError) setErrors(getApiErrors(addError));
		if (updateError) setErrors(getApiErrors(updateError));
	}, [addError, updateError, setErrors]);

	useEffect(() => {
		isEditing && initialState.name && setValues(initialState);
	}, [isEditing, initialState, setValues]);

	useEffect(() => {
		if (step && isAddSuccess) {
			dispatch(setThirdStateComplete());
			sendGaEvent(EGaEvents.SEND_CREATE_ADSPACE_SOURCE, {
				event_option1: EGaCategories.ONBOARDING,
				event_option2: EGaTypes.CONGRATULATION_POPUP,
			});
			return;
		}
		if (isAddSuccess || isUpdateSuccess) {
			sendGaEvent(isAddSuccess ? EGaEvents.SEND_CREATE_ADSPACE_SOURCE : EGaEvents.SEND_SAVE_ADSPACE_SOURCE, {
				event_option1: EGaCategories.SOURCES,
				event_option2: isAddSuccess ? EGaTypes.CREATING_SOURCES : EGaTypes.SAVING_SOURCES,
			});
			navigate(`/${EMainRoutes.SOURCES}`);
		}
	}, [isAddSuccess, isUpdateSuccess, step, navigate, dispatch]);

	return (
		<div {...props} className={cn(className, styles.sourceForm)}>
			<form onSubmit={handleSubmit} className={styles.form}>
				{isFetching && <OverlayLoader />}

				{(!step || step === EOnboardingSteps.SECOND) && (
					<div className={styles.section}>
						{!step && <Typography.Text>{t('Main info about your source')}</Typography.Text>}

						<Form.Item validateStatus={errors.name ? 'error' : ''} help={errors.name}>
							<Input
								value={values.name}
								onChange={(e) => {
									setFieldValue('name', e.target.value);
									!!step && sendGaEvent(EGaEvents.CLICK_SOURCE_NAME, step2EventOptions);
								}}
								placeholder={t('Source Name')}
								required
							/>
						</Form.Item>
						<Form.Item validateStatus={errors.url ? 'error' : ''} help={errors.url}>
							<Input
								value={values.url}
								onChange={(e) => setFieldValue('url', e.target.value)}
								placeholder={t('Link')}
							/>
						</Form.Item>
					</div>
				)}

				{(!step || step === EOnboardingSteps.THIRD) && (
					<div className={styles.section}>
						{!step && <Typography.Text>{t('Details about your source')}</Typography.Text>}

						<Select
							mode="multiple"
							placeholder={t('Verticals')}
							options={metaData?.categoryOptions}
							loading={isMetaLoading}
							value={values.categories}
							onChange={(value) => setFieldValue('categories', value)}
							maxTagCount="responsive"
							showSearch
							filterOption={(input, option) =>
								(option?.label?.toString() ?? '').toLowerCase().includes(input.toLowerCase())
							}
						/>

						<Select
							mode="multiple"
							placeholder={t('Specify countries')}
							options={metaData?.countryOptions}
							loading={isMetaLoading}
							value={values.countries}
							onChange={(value) => setFieldValue('countries', value)}
							maxTagCount="responsive"
							showSearch
							filterOption={(input, option) =>
								(option?.label?.toString() ?? '').toLowerCase().includes(input.toLowerCase())
							}
						/>

						<Select
							mode="multiple"
							placeholder={t('Specify types of traffic')}
							options={metaData?.trafficTypeOptions}
							loading={isMetaLoading}
							value={values.traffic_types}
							onChange={(value) => setFieldValue('traffic_types', value)}
							maxTagCount="responsive"
							showSearch
							filterOption={(input, option) =>
								(option?.label?.toString() ?? '').toLowerCase().includes(input.toLowerCase())
							}
						/>
					</div>
				)}

				{!step && (
					<div className={styles.buttons}>
						<Button type="default" size="large" onClick={() => navigate(`/${EMainRoutes.SOURCES}`)}>
							{t('Cancel')}
						</Button>

						<Button
							type="primary"
							size="large"
							htmlType="submit"
							loading={isAddLoading || isUpdateLoading}
							disabled={!isValid || !dirty}>
							{isEditing ? t('Save changes') : t('Create source')}
						</Button>
					</div>
				)}
				{!!step && (
					<div
						className={cn(styles.buttons, {
							[styles.buttons_step2]: step === EOnboardingSteps.SECOND,
						})}>
						{step === EOnboardingSteps.THIRD && (
							<Button
								type="default"
								size="large"
								onClick={() => {
									sendGaEvent(EGaEvents.CLICK_BACK, step3EventOptions);
									dispatch(setStep(EOnboardingSteps.SECOND));
								}}>
								{t('Back')}
							</Button>
						)}
						<div className={styles.buttons_right}>
							<Button onClick={handleGoToCatalog} type="default" ghost size="large">
								{t(`Go to Catalog`)}
							</Button>
							<Button
								type="primary"
								size="large"
								htmlType="submit"
								disabled={!isValid || !dirty}
								loading={isAddLoading}>
								{t('Next')}
							</Button>
						</div>
					</div>
				)}
			</form>
		</div>
	);
};
