import { i18n } from 'i18n';

import { ERawReportStatuses } from '../model/types';

type TReportStatuses = Record<ERawReportStatuses, { name: string; color: string }>;

export const REPORT_STATUSES: TReportStatuses = {
	[ERawReportStatuses.APPROVED]: {
		name: i18n.t('Approved'),
		color: '#7ec050',
	},
	[ERawReportStatuses.AVAILABLE]: {
		name: i18n.t('Available'),
		color: '#009cf4',
	},
	[ERawReportStatuses.DECLINED]: { name: i18n.t('Declined'), color: '#e47470' },
	[ERawReportStatuses.ON_HOLD]: { name: i18n.t('On Hold'), color: '#d79735' },
	[ERawReportStatuses.PAID]: { name: i18n.t('Paid'), color: '#b5b8bb' },
};

export const REPORT_STATUS_OPTIONS = Object.keys(REPORT_STATUSES).map((key) => ({
	label: REPORT_STATUSES[key as keyof typeof REPORT_STATUSES].name,
	value: key,
}));
