import { FC, HTMLAttributes, ReactNode, useEffect } from 'react';
import { useDispatch } from 'react-redux';
import { Outlet, ScrollRestoration, useLocation } from 'react-router-dom';

import { Layout } from 'antd';
import cn from 'classnames';

import { AppDispatch } from 'app/appStore';
//import { openOnboardingModal } from 'features/Onboarding';
import { useAppConfigRetrieveQuery } from 'shared/api';
import { ROUTES_WITHOUT_BOTTOM_BAR } from 'shared/consts';
import { BottomBar } from 'shared/ui';

import styles from './MainLayout.module.scss';

interface IMainLayoutProps extends HTMLAttributes<HTMLDivElement> {
	outlet?: ReactNode;
}

export const MainLayout: FC<IMainLayoutProps> = ({ className, outlet, ...props }) => {
	const { data: appConfig } = useAppConfigRetrieveQuery();
	const dispatch = useDispatch<AppDispatch>();
	const { pathname } = useLocation();

	const withBottomBar = !ROUTES_WITHOUT_BOTTOM_BAR.includes(pathname);

	useEffect(() => {
		if (!appConfig?.user) {
			return;
		}
		if (!appConfig.user?.balance) {
			//dispatch(openOnboardingModal());
		}
	}, [appConfig, dispatch]);

	return (
		<Layout {...props} className={cn(className, styles.layout, { [styles.withBottomBar]: withBottomBar })}>
			{/*(isFetching || !appConfig?.user) && <OverlayLoader opacity={1} zIndex={101} />*/}
			<ScrollRestoration />
			<Layout.Content className={styles.content}>{outlet || <Outlet />}</Layout.Content>
			{withBottomBar && <BottomBar />}
		</Layout>
	);
};
