import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';
import { useParams } from 'react-router-dom';

import cn from 'classnames';

import { CreateSourceLayout } from 'app/layouts';
import { useSourcesRetrieveQuery } from 'entities/Source';
import { Page, PageTitle } from 'shared/ui';
import { INITIAL_SOURCE_FORM_STATE } from 'widgets/SourceForm';

import styles from './EditSource.module.scss';

interface IEditSourceProps extends HTMLAttributes<HTMLDivElement> {}

export const EditSource: FC<IEditSourceProps> = ({ className, ...props }) => {
	const { t } = useTranslation();
	const { id } = useParams();
	const { data, isFetching } = useSourcesRetrieveQuery(id || '');
	const initialState = data?.uuid
		? {
				url: data?.url,
				name: data?.name,
				categories: data?.categories,
				countries: data?.countries,
				traffic_types: data?.traffic_types,
				uuid: data?.uuid,
			}
		: INITIAL_SOURCE_FORM_STATE;

	return (
		<Page {...props} className={cn(className, styles.editSource)}>
			<PageTitle>
				{t('Editing a Source')}: {data?.uuid}
			</PageTitle>

			<CreateSourceLayout initialState={initialState} isEditing isFetching={isFetching} sourceUuid={data?.uuid} />
		</Page>
	);
};

export default EditSource;
