import { FC, HTMLAttributes } from 'react';

import cn from 'classnames';

import styles from './BottomPanel.module.scss';

interface IBottomPanelProps extends HTMLAttributes<HTMLDivElement> {}

export const BottomPanel: FC<IBottomPanelProps> = ({ className, children, ...props }) => {
	return (
		<div {...props} className={cn(className, styles.bottomPanel)}>
			{children}
		</div>
	);
};
