import { FC, HTMLAttributes } from 'react';

import { Typography } from 'antd';
import cn from 'classnames';

import { useAppConfigRetrieveQuery } from 'shared/api';
import { Avatar } from 'shared/ui';

import styles from './ShortInfo.module.scss';

interface IShortInfoProps extends HTMLAttributes<HTMLDivElement> {}

export const ShortInfo: FC<IShortInfoProps> = ({ className, ...props }) => {
	const { data: appConfig } = useAppConfigRetrieveQuery();

	return (
		<div {...props} className={cn(className, styles.shortInfo)}>
			<Avatar isProfile size={'large'} />
			<Typography.Text>{appConfig?.user?.email}</Typography.Text>
		</div>
	);
};
