import { FC, lazy, PropsWithChildren, Suspense } from 'react';

import { OverlayLoader } from 'shared/ui';

const LazyCollection = lazy(() => import('./Collection.tsx'));

export const Collection: FC<PropsWithChildren> = (props) => (
	<Suspense fallback={<OverlayLoader />}>
		<LazyCollection {...props} />
	</Suspense>
);
