import { FC, HTMLAttributes } from 'react';

import { Button, Select, Typography } from 'antd';
import cn from 'classnames';

import { FULL_LANGUAGES } from 'shared/consts';

import { useChangeLanguage } from '../../hooks/useChangeLanguage';

import styles from './ChangeLanguage.module.scss';

interface IChangeLanguageProps extends HTMLAttributes<HTMLDivElement> {
	onModalClose: () => void;
}

export const ChangeLanguage: FC<IChangeLanguageProps> = ({ className, onModalClose, ...props }) => {
	const { t, lang, setLang, handleLangChange } = useChangeLanguage();

	return (
		<div {...props} className={cn(className, styles.content)}>
			<div className={styles.text}>
				<Typography.Title level={5} className={styles.title}>
					{t('Language change')}
				</Typography.Title>
				<Typography.Text className={styles.description}>
					{t(
						"This action will change the language of all account. If the changes wasn't applied, try to refresh the page.",
					)}
				</Typography.Text>
			</div>
			<Select
				className={styles.select}
				value={lang}
				options={FULL_LANGUAGES}
				onChange={(value) => {
					setLang(value);
				}}
				placeholder={t('Language')}
			/>
			<div className={styles.buttons}>
				<Button onClick={onModalClose} className={styles.cancelButton} size="large">
					{t('Cancel')}
				</Button>
				<Button
					onClick={() => {
						handleLangChange(lang);
						onModalClose();
					}}
					type="primary"
					size="large">
					{t('Change')}
				</Button>
			</div>
		</div>
	);
};
