import { FC, HTMLAttributes } from 'react';

import { Button, Form, Input, Typography } from 'antd';
import cn from 'classnames';

import { EMainRoutes } from 'shared/typings';

import { useProfileForm } from '../../hooks/useProfileForm';

import styles from './ProfileForm.module.scss';

interface ISourceFormProps extends HTMLAttributes<HTMLDivElement> {}

export const ProfileForm: FC<ISourceFormProps> = ({ className, ...props }) => {
	const { t, navigate, isLoading, values, handleSubmit, errors, setFieldValue, isValid, appConfig } = useProfileForm();

	return (
		<div {...props} className={cn(className, styles.editForm)}>
			<form onSubmit={handleSubmit} className={cn(className, styles.form)}>
				<Typography.Paragraph strong>{t('Personal information')}</Typography.Paragraph>
				<Form.Item validateStatus={errors?.telegram ? 'error' : ''} help={errors?.telegram}>
					<Input
						type="text"
						placeholder={t('Telegram account')}
						value={values.telegram}
						onChange={(e) => setFieldValue('telegram', e.target.value)}
					/>
				</Form.Item>
				<Form.Item validateStatus={errors?.whatsapp ? 'error' : ''} help={errors?.whatsapp}>
					<Input
						type="text"
						placeholder={t('WhatsApp')}
						value={values.whatsapp}
						onChange={(e) => setFieldValue('whatsapp', e.target.value)}
					/>
				</Form.Item>
				<Form.Item validateStatus={errors?.skype ? 'error' : ''} help={errors?.skype}>
					<Input
						type="text"
						placeholder={t('Skype account')}
						value={values.skype}
						onChange={(e) => setFieldValue('skype', e.target.value)}
					/>
				</Form.Item>

				{!!errors?.detail && <Typography.Paragraph type={'danger'}>{errors?.detail}</Typography.Paragraph>}

				<div className={styles.buttons}>
					<Button htmlType={'button'} size={'middle'} onClick={() => navigate(`/${EMainRoutes.PROFILE}`)}>
						{t('Cancel')}
					</Button>
					<Button
						htmlType={'submit'}
						type={'primary'}
						size={'middle'}
						disabled={appConfig?.is_super_login || !isValid || (!values.skype && !values.telegram && !values.whatsapp)}
						loading={isLoading}>
						{t('Save')}
					</Button>
				</div>
			</form>
		</div>
	);
};
