import { FC, Fragment, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import { Badge, type BadgeProps, Typography } from 'antd';
import cn from 'classnames';

import { SourcesRelationsRead, SourcesRelationsStatusEnum } from 'entities/Offer';
import { STATUSES } from 'shared/consts';
import { InfoTooltip } from 'shared/ui';

import styles from './JoinedSourceCard.module.scss';

const statusMap: Record<SourcesRelationsStatusEnum, BadgeProps['status']> = {
	[SourcesRelationsStatusEnum.Joined]: 'success',
	[SourcesRelationsStatusEnum.Rejected]: 'error',
	[SourcesRelationsStatusEnum.Verification]: 'warning',
};

interface IJoinedSourceCardProps extends HTMLAttributes<HTMLDivElement> {
	source: SourcesRelationsRead;
	isOfferDetails?: boolean;
}

export const JoinedSourceCard: FC<IJoinedSourceCardProps> = ({ className, source, isOfferDetails, ...props }) => {
	const { t } = useTranslation();
	const capDesc = t(
		'This CAP applies only to the current month and will not carry over to the next month if not fully used',
	);

	return (
		<div
			{...props}
			className={cn(className, styles.card, { [styles.card_details]: isOfferDetails }, [
				styles[`card_${source.status}`],
			])}>
			<dl className={styles.sourceId}>
				<dt className={styles.title}>{t('Source ID')}</dt>
				<dd className={styles.desc}>{source.source?.uuid}</dd>
			</dl>
			<dl
				className={cn(styles.body, {
					[styles.body_rejected]: source.status === SourcesRelationsStatusEnum.Rejected,
				})}>
				{source.status === SourcesRelationsStatusEnum.Joined && (
					<Fragment>
						<dt className={styles.title}>{t('Link from Offer')}</dt>
						<dd className={cn(styles.desc, styles.withIcon)}>
							<Typography.Text className={styles.affiliateLink} copyable ellipsis>
								{source?.affiliate_link}
							</Typography.Text>
						</dd>
						<dt className={cn(styles.title, styles.withIcon)}>
							{t('Cap')}
							<InfoTooltip text={capDesc} />
						</dt>
						<dd className={styles.desc}>{source.cap}</dd>
					</Fragment>
				)}
				{source.status === SourcesRelationsStatusEnum.Rejected && (
					<Fragment>
						<dt className={styles.title}>{t('Rejection reason')}</dt>
						<dd className={cn(styles.desc, styles.desc_rejected)}>{source.rejection_comment}</dd>
					</Fragment>
				)}
			</dl>
			{source.status && <Badge status={statusMap[source.status]} text={STATUSES[source.status]} />}
		</div>
	);
};
