import { FC, lazy, PropsWithChildren, Suspense } from 'react';

import { OverlayLoader } from 'shared/ui';

const LazyCreateCollection = lazy(() => import('./CreateCollection.tsx'));

export const CreateCollection: FC<PropsWithChildren> = (props) => (
	<Suspense fallback={<OverlayLoader />}>
		<LazyCreateCollection {...props} />
	</Suspense>
);
