import { createSlice, PayloadAction } from '@reduxjs/toolkit';

import { MOCK_IPost } from 'shared/consts/MOCK_FOR_CATALOG';

interface IBrandSlice {
	isOpenCreateCollectionDrawer: boolean;
	isOpenDetailsPopup: boolean;
	isOpenSaveToCollectionsDrawer: boolean;
	post: MOCK_IPost | null;
}

const initialState: IBrandSlice = {
	isOpenSaveToCollectionsDrawer: false,
	isOpenCreateCollectionDrawer: false,
	isOpenDetailsPopup: false,
	post: null,
};

export const brandSlice = createSlice({
	name: 'brand',
	initialState,
	reducers: {
		setIsOpenSaveToCollectionsDrawer: (state, action: PayloadAction<boolean>) => {
			state.isOpenSaveToCollectionsDrawer = action.payload;
			if (!action.payload) {
				state.isOpenDetailsPopup = false;
				state.post = null;
			}
		},
		setIsOpenCreateCollectionDrawer: (state, action: PayloadAction<boolean>) => {
			state.isOpenCreateCollectionDrawer = action.payload;
			if (!action.payload) {
				state.isOpenSaveToCollectionsDrawer = false;
				state.isOpenDetailsPopup = false;
				state.post = null;
			}
		},
		setIsOpenDetailsPopup: (state, action: PayloadAction<boolean>) => {
			state.isOpenDetailsPopup = action.payload;
			if (!action.payload) {
				state.post = null;
			}
		},
		setPost: (state, action: PayloadAction<MOCK_IPost | null>) => {
			state.post = action.payload;
		},
	},
});

export default brandSlice.reducer;

export const { setIsOpenCreateCollectionDrawer, setIsOpenDetailsPopup, setIsOpenSaveToCollectionsDrawer, setPost } =
	brandSlice.actions;
