import { FC, HTMLAttributes, useState } from 'react';
import { useTranslation } from 'react-i18next';

import { Button, Modal, Typography } from 'antd';
import cn from 'classnames';

import { useAppConfigRetrieveQuery } from 'shared/api';
import { CURRENCIES, FULL_LANGUAGES } from 'shared/consts';
import { InfoTooltip } from 'shared/ui';

import { ChangeLanguage } from '../ChangeLanguage/ChangeLanguage';

import styles from './AccountSett.module.scss';
const PASSPORT_URL = import.meta.env.VITE_PASSPORT_URL;

interface IAccountSettingsProps extends HTMLAttributes<HTMLDivElement> {}

export const AccountSett: FC<IAccountSettingsProps> = ({ className, ...props }) => {
	const { data: appConfig } = useAppConfigRetrieveQuery();
	const { t } = useTranslation();
	const [modalIsOpen, setModalIsOpen] = useState(false);

	return (
		<>
			<Modal open={modalIsOpen} onCancel={() => setModalIsOpen(false)} destroyOnHidden footer={null}>
				<ChangeLanguage onModalClose={() => setModalIsOpen(false)} />
			</Modal>

			<div {...props} className={cn(className, styles.table)}>
				<div className={styles.header}>
					<Typography.Text className={styles.headerTitle}>{t('Account settings')}</Typography.Text>
					<div className={styles.header_sub}>
						<Typography.Text type="secondary" className={styles.header_desc}>
							{t('You will be redirected to Mitgo ID')}
						</Typography.Text>
						<Button type="link" href={PASSPORT_URL}>
							{t('My Passport ID')}
						</Button>
					</div>
				</div>
				<dl className={styles.body}>
					<dt className={styles.dt}>
						<Typography.Text type="secondary">{t('Email / Login')}</Typography.Text>
					</dt>
					<dd className={styles.dd}>
						<Typography.Text>{appConfig?.user?.email}</Typography.Text>
					</dd>

					<dt className={styles.dt}>
						<Typography.Text type="secondary">{t('Password')}</Typography.Text>
					</dt>
					<dd className={styles.dd}>
						<Typography.Text>••••••••••••</Typography.Text>
						<Button type="link" href={PASSPORT_URL}>
							{t('Change')}
						</Button>
					</dd>

					<dt className={styles.dt}>
						<Typography.Text type="secondary">{t('Currency')}</Typography.Text>
					</dt>
					<dd className={cn(styles.dd, styles.dd_info)}>
						<Typography.Text>
							{appConfig?.user?.balance?.currency},{' '}
							{CURRENCIES[(appConfig?.user?.balance?.currency as keyof typeof CURRENCIES) || 'USD']}
						</Typography.Text>
						<InfoTooltip text={t("You can't change currency")} />
					</dd>

					<dt className={cn(styles.dt, styles.dt_last)}>
						<Typography.Text type="secondary">{t('Language')}</Typography.Text>
					</dt>
					<dd className={cn(styles.dd, styles.dd_last)}>
						<Typography.Text>
							{FULL_LANGUAGES.find((fl) => fl.value === appConfig?.user?.language)?.label}
						</Typography.Text>
						<Button type="link" onClick={() => setModalIsOpen(true)}>
							{t('Change')}
						</Button>
					</dd>
				</dl>
			</div>
		</>
	);
};
