import { combineReducers } from '@reduxjs/toolkit';

import brandSlice from 'entities/Brand/model/brandSlice';
import notificationsSlice from 'entities/Notification/model/notificationsSlice';
import joinOfferSlice from 'features/JoinOffer/model/joinOfferSlice';
import onboardingSlice from 'features/Onboarding/model/onboardingSlice';
import { baseApi } from 'shared/api/baseApi';
import commonSlice from 'shared/model/commonSlice';
import offerListReducer from 'widgets/OfferList/model/offerListSlice';
import sidebarReducer from 'widgets/Sidebar/model/sidebarSlice';

export const rootReducer = combineReducers({
	sidebarReducer,
	brandSlice,
	commonSlice,
	joinOfferSlice,
	onboardingSlice,
	notificationsSlice,
	offerList: offerListReducer,
	[baseApi.reducerPath]: baseApi.reducer,
});
