import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import { Typography } from 'antd';

import { EInternalEmails } from 'shared/typings';
import { Faq, IFaqItem, Page, PageTitle } from 'shared/ui';
import { ProfileForm } from 'widgets/ProfileForm';

import styles from './EditProfile.module.scss';

interface IEditProfileProps extends HTMLAttributes<HTMLDivElement> {}

export const EditProfile: FC<IEditProfileProps> = ({ ...props }) => {
	const { t } = useTranslation();
	const faqItems = [
		{
			title: t('Why do we need your contacts?'),
			text: t('We need your contacts to help you immediately, if anything goes wrong or you will have any questions.'),
		},
	];
	return (
		<Page {...props} className={styles.main}>
			<PageTitle>{t('Profile Editing')}</PageTitle>
			<div className={styles.edit}>
				<ProfileForm />
				<div className={styles.info}>
					<Faq items={faqItems as IFaqItem[]} />
					<Typography.Link href={`mailto:${EInternalEmails.SUPPORT}`}>{t('Need help?')}</Typography.Link>
				</div>
			</div>
		</Page>
	);
};

export default EditProfile;
