import { OfferRead } from 'entities/Offer';
import { TLabelValue } from 'shared/typings';

export type TSourceOption = TLabelValue & {
	isUnAvailable?: boolean;
};

export type TSourceItem = {
	value: string | null;
	options: TLabelValue[];
	warnings?: string[];
};
export interface joinOfferState {
	offer: OfferRead | null;
	modalIsOpened: boolean;
	state: EJoinStates.RULES | EJoinStates.SOURCES;
	specifiedSource: string | null;
	sourceOptions: TSourceOption[];
	selectedSources: TSourceItem[];
	isInitState: boolean;
	isNothingToSelect: boolean;
}

export enum EJoinStates {
	SOURCES = 'sources',
	RULES = 'rules',
}

export enum ESourceTabs {
	JOIN = 'join',
	LIST = 'list',
}
