import { FC } from 'react';

import type { AvatarProps } from 'antd';
import { Avatar as AvatarAnt } from 'antd';
import cn from 'classnames';

import { useAppConfigRetrieveQuery } from 'shared/api';

import styles from './Avatar.module.scss';

interface IAvatarProps extends AvatarProps {
	className?: string;
	isProfile?: boolean;
}

export const Avatar: FC<IAvatarProps> = ({ className, isProfile, ...props }) => {
	const { data: appConfig } = useAppConfigRetrieveQuery();
	const shortName = appConfig?.user?.email?.slice(0, 2)?.toUpperCase();

	return (
		<AvatarAnt className={cn(className, styles.avatar, { [styles.avatar_profile]: isProfile })} {...props}>
			{shortName}
		</AvatarAnt>
	);
};
