import {
	BaseQueryFn,
	FetchArgs,
	fetchBaseQuery,
	FetchBaseQueryError,
	FetchBaseQueryMeta,
} from '@reduxjs/toolkit/query/react';
import { isTMA, retrieveRawInitData } from '@telegram-apps/bridge';

import { notification } from 'antd';

import { EErrorCodes, EMainRoutes } from 'shared/typings';

export const baseQuery: BaseQueryFn<string | FetchArgs, unknown, FetchBaseQueryError, {}, FetchBaseQueryMeta> = async (
	args,
	api,
	extraOptions,
) => {
	const result = await fetchBaseQuery({
		baseUrl: '/',
		prepareHeaders: (headers) => {
			if (isTMA()) {
				const initDataRaw = retrieveRawInitData();
				headers.append('Authorization', `tma ${initDataRaw}`);
			}

			return headers;
		},
		paramsSerializer: (params) => {
			const searchParams = new URLSearchParams();

			Object.entries(params).forEach(([key, value]) => {
				if (Array.isArray(value)) {
					value.forEach((v) => searchParams.append(key, v));
				} else if (value !== null && value !== undefined) {
					searchParams.append(key, value.toString());
				}
			});

			return searchParams.toString();
		},
	})(args, api, extraOptions);

	const statusCode = result.meta?.response?.status;

	if (statusCode === EErrorCodes.UNAUTHORIZED || statusCode === EErrorCodes.FORBIDDEN) {
		window.location.replace(`/${EMainRoutes.ACCOUNT}/${EMainRoutes.LOG_IN}`);
	}

	if (
		statusCode === EErrorCodes.BAD_REQUEST ||
		statusCode === EErrorCodes.BAD_GATEWAY ||
		statusCode === EErrorCodes.INTERNAL_SERVER_ERRROR ||
		statusCode === EErrorCodes.TOO_MANY_REQUESTS ||
		statusCode === EErrorCodes.PAGE_NOT_FOUND
	) {
		const text = result.meta?.response?.statusText;

		notification.open({
			message: `${statusCode} - ${text}`,
			type: 'error',
			placement: 'topRight',
			showProgress: true,
			pauseOnHover: true,
		});
	}

	return result;
};
